mapper.select:


     and A.customer_id = #{brtCustomerDeliveryVo.customerId}
     and A.order_id = #{brtCustomerDeliveryVo.orderId}
     and A.order_node_id = #{brtCustomerDeliveryVo.orderNodeId}
     and A.delivery_status = #{brtCustomerDeliveryVo.deliveryStatus}

order by A.create_time desc

SELECT so.delivery_time deliveryTime, -- 计划送货日期 c.customer_name customerName, -- 客户名称 omp.update_time updateTime, -- 送货日期 ifnull(m.materiel_name,omp.materiel_id) materielName, -- 产品名称 ifnull(omp.order_num,0) detailsNum, -- 销售数量 ifnull(omp.materiel_num,0) fulfillNum, -- 已送货数量 ifnull(omp.order_num,0)-ifnull(omp.materiel_num,0) surplusNum, -- 剩余数量 so.order_remark remark, -- 备注 so.delivery_address address, -- 送货地址 so.order_no orderNo, -- 关联业务 m.files imgPath, -- 图片 so.order_id orderId, so.customer_id customerId, p1.handle, m.materiel_id materielId, so.template_id templateId FROM brt_sales_order so inner join brt_customer_delivery cd on cd.order_id = so.order_id inner join brt_sales_order_details sod on sod.order_id = so.order_id inner join brt_order_materiel_plan omp on omp.order_details_id = sod.details_id and omp.order_node_id = cd.order_node_id left JOIN brt_materiel m on m.materiel_id = omp.materiel_id left join brt_customer c on so.customer_id = c.customer_id left join ( select p.orderId, if(p.orderNum-p.materielNum >0,if(p.materielNum=0,'送货','部分送货'),'全部送货') handle from ( SELECT so.order_id orderId, sum(ifnull( omp.order_num, 0 )) orderNum, sum(ifnull( omp.materiel_num, 0 )) materielNum FROM brt_sales_order so inner join brt_customer_delivery cd on cd.order_id = so.order_id INNER JOIN brt_sales_order_details sod ON sod.order_id = so.order_id INNER JOIN brt_order_materiel_plan omp ON omp.order_details_id = sod.details_id and omp.order_node_id = cd.order_node_id GROUP BY so.order_id )p )p1 on p1.orderId = so.order_id
and so.customer_id = #{deliveryRemindVo.customerId}
and omp.update_time >= str_to_date(#{deliveryRemindVo.timeStart},"%Y-%m-%d")
and omp.update_time <= str_to_date(#{deliveryRemindVo.timeEnd},"%Y-%m-%d")
and c.customer_name like concat('%',#{deliveryRemindVo.customerName},'%')
and c.type_id = #{deliveryRemindVo.customerType}
and m.materiel_id = #{deliveryRemindVo.materielId}
and so.order_no like concat('%',#{deliveryRemindVo.orderNo},'%')
and p1.handle in
#{item}
and so.delivery_address like concat('%',#{deliveryRemindVo.address},'%')

SELECT so.order_id orderId, c.customer_name customerName, -- 客户名称 omp.update_time updateTime, -- 送货日期 ifnull(m.materiel_name,omp.materiel_id) materielName, -- 产品名称 ifnull(omp.order_num,0) detailsNum, -- 销售数量 ifnull(omp.materiel_num,0) fulfillNum, -- 已送货数量 ifnull(omp.order_num,0)-ifnull(omp.materiel_num,0) surplusNum, -- 剩余数量 omp.plan_id planId, 0 thisNum
FROM brt_sales_order so inner join brt_customer_delivery cd on cd.order_id = so.order_id inner join brt_sales_order_details sod on sod.order_id = so.order_id inner join brt_order_materiel_plan omp on omp.order_details_id = sod.details_id and omp.order_node_id = cd.order_node_id left JOIN brt_materiel m on m.materiel_id = omp.materiel_id left join brt_customer c on so.customer_id = c.customer_id
where so.order_id = #{orderId}
